import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> [price, qty, side, active]
    arrival_counter = 0

    def clean_buy():
        while buy_heap:
            negprice, arr, oid = buy_heap[0]
            if oid not in book:
                heapq.heappop(buy_heap)
                continue
            o = book[oid]
            if not o[3] or o[1] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            price, arr, oid = sell_heap[0]
            if oid not in book:
                heapq.heappop(sell_heap)
                continue
            o = book[oid]
            if not o[3] or o[1] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                o = book[oid]
                if o[3] and o[1] > 0:
                    o[3] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                sprice, sarr, soid = sell_heap[0]
                if price is not None and sprice > price:
                    break
                sorder = book[soid]
                trade_qty = min(remaining, sorder[1])
                trades.append([oid, soid, sprice, trade_qty])
                remaining -= trade_qty
                sorder[1] -= trade_qty
                if sorder[1] == 0:
                    heapq.heappop(sell_heap)
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, barr, boid = buy_heap[0]
                bprice = -negprice
                if price is not None and bprice < price:
                    break
                border = book[boid]
                trade_qty = min(remaining, border[1])
                trades.append([boid, oid, bprice, trade_qty])
                remaining -= trade_qty
                border[1] -= trade_qty
                if border[1] == 0:
                    heapq.heappop(buy_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = [price, remaining, side, True]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival_counter, oid))
            arrival_counter += 1
        else:
            # ioc, market, or fully filled limit - not resting
            if typ == 'limit':
                # fully filled, mark as filled (not active for cancel purposes)
                book[oid] = [price, 0, side, False]
            arrival_counter += 1

    return trades

